// ❌ OLD: JNI requires a Java native method declaration, a generated C
// header (javac -h), a C implementation that uses JNIEnv, a compiled
// shared library, and System.loadLibrary — plus manual management of
// native memory and no bounds checking.
public class MathJNI {
  static {
    System.loadLibrary("mathjni"); // ❌ OLD: must build & ship a .so/.dll
  }

  // ❌ OLD: declared native, implemented in C:
  // JNIEXPORT jdouble JNICALL Java_MathJNI_sqrtNative
  //   (JNIEnv *env, jclass, jdouble x) { return sqrt(x); }
  public static native double sqrtNative(double x);

  public static void main(String[] args) {
    System.out.println(sqrtNative(16.0)); // calls through JNI
  }
}

import java.lang.foreign.*;
import java.lang.invoke.MethodHandle;

// ✅ NEW: The FFM API binds the C library function directly to a
// MethodHandle — no native method declaration, no C header, no
// generated JNI glue.
public class MathFFM {
  public static void main(String[] args) throws Throwable {
    Linker linker = Linker.nativeLinker(); // ✅ NEW: ABI linker
    SymbolLookup lookup = linker.defaultLookup();

    // ✅ NEW: bind the C sqrt function to a MethodHandle
    MethodHandle sqrt = linker.downcallHandle(
        lookup.find("sqrt").orElseThrow(),
        FunctionDescriptor.of(ValueLayout.JAVA_DOUBLE, ValueLayout.JAVA_DOUBLE));

    System.out.println(sqrt.invokeExact(16.0)); // ✅ NEW: call it directly

    // Memory: try (Arena arena = Arena.ofConfined()) {
    //   MemorySegment seg = arena.allocate(ValueLayout.JAVA_INT);
    //   seg.set(ValueLayout.JAVA_INT, 0, 42); // bounds-checked
    // } // arena close frees the memory deterministically
  }
}
